:root {
  --bg: #1e1e2f;
  --card: #2a2a40;
  --text: #f0e6d2;
  --accent: #ffb347;
  --accent-2: #6bcb77;
  --accent-3: #4d96ff;
  --danger: #ff6b6b;
  --radius: 16px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle at 50% 30%, #2e2e4a 0%, var(--bg) 70%);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  width: 100%;
  max-width: 400px;
  background: var(--card);
  border-radius: var(--radius);
  padding: 24px 20px 28px;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.45);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

h1 {
  font-size: 1.6rem;
  letter-spacing: 0.5px;
  color: var(--accent);
}

/* Pet */
.pet-stage {
  width: 140px;
  height: 140px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #232338;
  border-radius: 50%;
  border: 4px solid #3a3a55;
}

.pet {
  position: relative;
  width: 90px;
  height: 90px;
  background: var(--accent-2);
  border-radius: 45% 45% 40% 40%;
  box-shadow: inset -6px -6px 0 rgba(0, 0, 0, 0.15);
  transition: transform 0.2s ease;
}

.pet:hover {
  transform: scale(1.05);
}

.pet-eye {
  position: absolute;
  top: 30px;
  width: 12px;
  height: 16px;
  background: #1e1e2f;
  border-radius: 50%;
}

.pet-eye.left { left: 22px; }
.pet-eye.right { right: 22px; }

.pet-mouth {
  position: absolute;
  bottom: 22px;
  left: 50%;
  transform: translateX(-50%);
  width: 24px;
  height: 12px;
  border-bottom: 4px solid #1e1e2f;
  border-radius: 0 0 50% 50%;
  transition: all 0.2s ease;
}

.pet.sad .pet-mouth {
  height: 8px;
  border-bottom: none;
  border-top: 4px solid #1e1e2f;
  border-radius: 50% 50% 0 0;
  bottom: 16px;
}

.pet-cheek {
  position: absolute;
  top: 52px;
  width: 14px;
  height: 8px;
  background: rgba(255, 107, 107, 0.5);
  border-radius: 50%;
}

.pet-cheek.left { left: 10px; }
.pet-cheek.right { right: 10px; }

/* Mood */
.mood {
  font-size: 1.1rem;
  font-weight: 600;
  text-align: center;
  min-height: 1.4em;
  color: var(--accent);
  transition: color 0.3s ease;
}

/* Bars */
.bars {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.bar-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.bar-label {
  display: flex;
  justify-content: space-between;
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text);
}

.bar-track {
  width: 100%;
  height: 14px;
  background: #1e1e2f;
  border-radius: 8px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  width: 80%;
  border-radius: 8px;
  transition: width 0.4s ease, background-color 0.3s ease;
}

.bar-fill.hunger { background: var(--accent); }
.bar-fill.happiness { background: var(--accent-2); }
.bar-fill.energy { background: var(--accent-3); }

.bar-fill.low { background: var(--danger); }

/* Controls */
.controls {
  display: flex;
  gap: 12px;
  width: 100%;
  flex-wrap: wrap;
  justify-content: center;
}

.btn {
  flex: 1 1 0;
  min-width: 90px;
  padding: 12px 16px;
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 700;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  color: #1e1e2f;
  background: var(--accent);
  transition: transform 0.1s ease, filter 0.2s ease, box-shadow 0.2s ease;
  box-shadow: 0 4px 0 rgba(0, 0, 0, 0.3);
}

.btn.play { background: var(--accent-2); }
.btn.sleep { background: var(--accent-3); color: #fff; }

.btn:hover {
  filter: brightness(1.1);
  transform: translateY(-1px);
}

.btn:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 3px;
}

.btn:active {
  transform: translateY(2px);
  box-shadow: 0 2px 0 rgba(0, 0, 0, 0.3);
}

@media (max-width: 380px) {
  .card { padding: 20px 14px 24px; }
  .btn { min-width: 70px; padding: 10px 8px; font-size: 0.95rem; }
  .pet-stage { width: 120px; height: 120px; }
  .pet { width: 76px; height: 76px; }
  .pet-eye { top: 24px; }
  .pet-eye.left { left: 18px; }
  .pet-eye.right { right: 18px; }
  .pet-mouth { bottom: 18px; }
  .pet-cheek { top: 44px; }
  .pet-cheek.left { left: 8px; }
  .pet-cheek.right { right: 8px; }
}

const state = {
  hunger: 80,
  happiness: 80,
  energy: 80,
  sleeping: false,
};

const els = {
  hungerFill: document.getElementById('hunger-fill'),
  happinessFill: document.getElementById('happiness-fill'),
  energyFill: document.getElementById('energy-fill'),
  hungerValue: document.getElementById('hunger-value'),
  happinessValue: document.getElementById('happiness-value'),
  energyValue: document.getElementById('energy-value'),
  hungerBar: document.getElementById('hunger-bar'),
  happinessBar: document.getElementById('happiness-bar'),
  energyBar: document.getElementById('energy-bar'),
  mood: document.getElementById('mood'),
  pet: document.getElementById('pet'),
};

function clamp(v) {
  return Math.max(0, Math.min(100, Math.round(v)));
}

function updateUI() {
  const values = [
    ['hunger', state.hunger],
    ['happiness', state.happiness],
    ['energy', state.energy],
  ];

  for (const [key, val] of values) {
    const fill = els[key + 'Fill'];
    const text = els[key + 'Value'];
    const track = els[key + 'Bar'];
    fill.style.width = val + '%';
    text.textContent = val + '%';
    track.setAttribute('aria-valuenow', val);
    fill.classList.toggle('low', val < 25);
  }

  updateMood();
}

function updateMood() {
  const { hunger, happiness, energy } = state;
  let mood = '';
  let sad = false;

  if (state.sleeping) {
    mood = 'Zzz... your pet is sleeping.';
  } else if (hunger < 25) {
    mood = 'Your pet is very hungry!';
    sad = true;
  } else if (energy < 25) {
    mood = 'Your pet is exhausted.';
    sad = true;
  } else if (happiness < 25) {
    mood = 'Your pet feels lonely.';
    sad = true;
  } else if (hunger > 70 && happiness > 70 && energy > 70) {
    mood = 'Your pet is thriving!';
  } else {
    mood = 'Your pet is doing okay.';
  }

  els.mood.textContent = mood;
  els.pet.classList.toggle('sad', sad);
}

function decay() {
  if (state.sleeping) {
    state.energy = clamp(state.energy + 2);
    state.hunger = clamp(state.hunger - 1);
    if (state.energy >= 100) {
      state.sleeping = false;
    }
  } else {
    state.hunger = clamp(state.hunger - 1);
    state.happiness = clamp(state.happiness - 1);
    state.energy = clamp(state.energy - 1);
  }
  updateUI();
}

function feed() {
  if (state.sleeping) return;
  state.hunger = clamp(state.hunger + 15);
  state.happiness = clamp(state.happiness + 5);
  updateUI();
}

function play() {
  if (state.sleeping) return;
  state.happiness = clamp(state.happiness + 15);
  state.energy = clamp(state.energy - 10);
  state.hunger = clamp(state.hunger - 5);
  updateUI();
}

function sleep() {
  if (state.sleeping) {
    state.sleeping = false;
  } else {
    state.sleeping = true;
  }
  updateUI();
}

document.getElementById('feed-btn').addEventListener('click', feed);
document.getElementById('play-btn').addEventListener('click', play);
document.getElementById('sleep-btn').addEventListener('click', sleep);

setInterval(decay, 4000);
updateUI();
